import { join } from "node:path";
import {
  begin,
  validate,
  pack,
  resume,
  loadTask,
  loadConfig,
  ToolFailure,
} from "./tool.ts";
import { toolMessages } from "./tool-config.ts";

import { summarizeIssueOutput } from "./output.ts";

const [command, argument] = process.argv.slice(2);
try {
  const config = await loadConfig();
  if (!command || !config.toolCommands.includes(command) || !argument)
    throw new ToolFailure({
      file: "command",
      pointer: "",
      check: "arguments",
      category: "input",
      message: toolMessages.cliArguments,
      action: toolMessages.cliAction,
    });
  let result: unknown;
  switch (command) {
    case "begin":
      result = await begin(argument);
      break;
    case "validate":
      result = await validate(argument);
      break;
    case "pack":
      result = await pack(argument);
      break;
    case "resume":
      result = await resume(argument);
      break;
    case "preview": {
      const task = await loadTask(argument);
      const { runPreviewForeground } = await import("./preview.ts");
      await runPreviewForeground(task.outputDirectory);
      break;
    }
    case "formal": {
      const task = await loadTask(argument);
      const { verifyFormalPackage } = await import("./formal.ts");
      result = await verifyFormalPackage(
        join(task.outputDirectory, config.zipFile),
        join(task.outputDirectory, "formal"),
      );
      break;
    }
  }
  if (command === "preview") process.exit();
  result = summarizeIssueOutput(result, config.maxDisplayedIssues);
  process.stdout.write(JSON.stringify(result, null, 2) + "\n");
  if (
    result &&
    typeof result === "object" &&
    "passed" in result &&
    result.passed === false
  )
    process.exitCode = 1;
} catch (error) {
  process.stdout.write(
    JSON.stringify(
      {
        passed: false,
        diagnostic:
          error instanceof ToolFailure
            ? error.diagnostic
            : {
                file: argument ?? "command",
                pointer: "",
                check: command ?? "arguments",
                category: "tool",
                message: String(error),
                action: toolMessages.cliFallbackAction,
              },
      },
      null,
      2,
    ) + "\n",
  );
  process.exitCode = 1;
}

